//! Tests for the Planetoid citation-graph loader.
//!
//! The fixture is a miniature dataset in the exact Planetoid
//! format (eight files, pickle protocol 2, numpy arrays, scipy
//! CSR matrices, a defaultdict of adjacency lists), generated by
//! `tools/gen_planetoid_fixture.py` in the program records. The
//! expected values were computed by the canonical numpy assembly
//! on the same objects, so the loader is checked against the
//! reference construction, not against itself.

use std::path::PathBuf;

use wyrd_graph::gcn::{normalized_adjacency, Gcn, GcnRecipe};
use wyrd_graph::planetoid::{load_planetoid, PLANETOID_LOADER_VERSION};

#[rustfmt::skip]
#[path = "planetoid_fixture/fixture.rs"]
mod fixture;

#[rustfmt::skip]
#[path = "planetoid_fixture/fixture_py2.rs"]
mod fixture_py2;

fn hex_decode(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "hex fixture has odd length");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex fixture"))
        .collect()
}

fn write_files(dir: &std::path::Path, files: [(&str, &str); 8]) {
    for (name, hex) in files {
        std::fs::write(dir.join(name), hex_decode(hex)).expect("write fixture file");
    }
}

fn fixture_dir(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("wyrd-planetoid-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create fixture dir");
    write_files(
        &dir,
        [
            ("ind.cora.x", fixture::X),
            ("ind.cora.y", fixture::Y),
            ("ind.cora.tx", fixture::TX),
            ("ind.cora.ty", fixture::TY),
            ("ind.cora.allx", fixture::ALLX),
            ("ind.cora.ally", fixture::ALLY),
            ("ind.cora.graph", fixture::GRAPH),
            ("ind.cora.test.index", fixture::TEST_INDEX),
        ],
    );
    dir
}

fn fixture_py2_dir(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("wyrd-planetoid-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create fixture dir");
    write_files(
        &dir,
        [
            ("ind.cora.x", fixture_py2::X),
            ("ind.cora.y", fixture_py2::Y),
            ("ind.cora.tx", fixture_py2::TX),
            ("ind.cora.ty", fixture_py2::TY),
            ("ind.cora.allx", fixture_py2::ALLX),
            ("ind.cora.ally", fixture_py2::ALLY),
            ("ind.cora.graph", fixture_py2::GRAPH),
            ("ind.cora.test.index", fixture_py2::TEST_INDEX),
        ],
    );
    dir
}

#[test]
fn loader_version_is_stable() {
    assert_eq!(PLANETOID_LOADER_VERSION, "wyrd-graph planetoid v1");
}

#[test]
fn loads_fixture_and_matches_reference_assembly() {
    let dir = fixture_dir("assembly");
    let loaded = load_planetoid(&dir);
    let _ = std::fs::remove_dir_all(&dir);
    let data = &loaded.data;
    assert_eq!(data.node_count(), fixture::NODES);
    assert_eq!(data.feature_count(), fixture::WIDTH);
    assert_eq!(data.class_count(), fixture::CLASSES);
    assert_eq!(data.labels, fixture::EXPECTED_LABELS);
    assert_eq!(data.features.len(), fixture::NODES);
    for (row, expected) in data.features.iter().zip(fixture::EXPECTED_FEATURES.iter()) {
        assert_eq!(row.as_slice(), *expected);
    }
    assert_eq!(loaded.edges, fixture::EXPECTED_EDGES);
    assert_eq!(data.train, fixture::EXPECTED_TRAIN);
    assert_eq!(data.validation, fixture::EXPECTED_VALIDATION);
    assert_eq!(data.test, fixture::EXPECTED_TEST);
    // The splits are disjoint and inside the node range.
    let mut seen = std::collections::BTreeSet::new();
    for split in [&data.train, &data.validation, &data.test] {
        for &node in split {
            assert!(node < fixture::NODES);
            assert!(seen.insert(node), "node {node} in two splits");
        }
    }
}

#[test]
fn py2_era_spellings_load_to_the_same_assembly() {
    // The sealed Cora files are Python-2-era artifacts whose
    // spellings (raw string array data, the copyreg reconstructor,
    // the __builtin__ factory) the modern fixture never produces.
    // The era-2 fixture carries the same dataset in those
    // spellings and must assemble identically.
    let dir = fixture_py2_dir("py2");
    let loaded = load_planetoid(&dir);
    let _ = std::fs::remove_dir_all(&dir);
    let data = &loaded.data;
    assert_eq!(data.labels, fixture::EXPECTED_LABELS);
    assert_eq!(data.features.len(), fixture::NODES);
    for (row, expected) in data.features.iter().zip(fixture::EXPECTED_FEATURES.iter()) {
        assert_eq!(row.as_slice(), *expected);
    }
    assert_eq!(loaded.edges, fixture::EXPECTED_EDGES);
    assert_eq!(data.train, fixture::EXPECTED_TRAIN);
    assert_eq!(data.validation, fixture::EXPECTED_VALIDATION);
    assert_eq!(data.test, fixture::EXPECTED_TEST);
}

#[test]
fn loaded_graph_trains_under_the_default_recipe() {
    let dir = fixture_dir("train");
    let loaded = load_planetoid(&dir);
    let _ = std::fs::remove_dir_all(&dir);
    let data = &loaded.data;
    let a_hat = normalized_adjacency(data.node_count(), &loaded.edges);
    let recipe = GcnRecipe::default();
    let mut model = Gcn::new(data.feature_count(), data.class_count(), &recipe);
    let history = model.train(&a_hat, data, &recipe);
    assert_eq!(history.len(), recipe.epochs);
    assert!(history.iter().all(|loss| loss.is_finite()));
    // Training must actually learn on the loaded graph: a loader
    // that scrambled features against labels would not bring the
    // training loss down like this.
    assert!(
        history[recipe.epochs - 1] < history[0],
        "training loss did not fall: {} to {}",
        history[0],
        history[recipe.epochs - 1]
    );
}

#[test]
#[should_panic(expected = "cannot read")]
fn missing_file_panics() {
    let dir = std::env::temp_dir().join(format!("wyrd-planetoid-empty-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create empty dir");
    let _ = load_planetoid(&dir);
}

#[test]
#[should_panic(expected = "not a dict of adjacency lists")]
fn graph_of_wrong_shape_panics() {
    let dir = fixture_dir("badgraph");
    // A pickle of the integer 42 where the graph belongs.
    std::fs::write(dir.join("ind.cora.graph"), b"I42\n.").expect("overwrite graph");
    let _ = load_planetoid(&dir);
}

#[test]
#[should_panic(expected = "outside the subset")]
fn unknown_global_panics() {
    let dir = fixture_dir("badglobal");
    std::fs::write(dir.join("ind.cora.allx"), b"\x80\x02cfoo\nbar\n)R.").expect("overwrite allx");
    let _ = load_planetoid(&dir);
}

#[test]
#[should_panic(expected = "outside the subset")]
fn truncated_pickle_panics() {
    let dir = fixture_dir("truncated");
    let ally = hex_decode(fixture::ALLY);
    std::fs::write(dir.join("ind.cora.ally"), &ally[..ally.len() / 2]).expect("truncate ally");
    let _ = load_planetoid(&dir);
}
